#include <iostream>
#include <algorithm>

int main() {
    struct Case {
        std::vector<int> nums;
        int target;
        std::vector<int> expected;
    };

    std::vector<Case> cases = {
        {{2, 7, 11, 15}, 9, {0, 1}},
        {{3, 2, 4}, 6, {1, 2}},
        {{3, 3}, 6, {0, 1}}
    };

    int passed = 0;
    for (size_t i = 0; i < cases.size(); ++i) {
        auto& c = cases[i];
        try {
            std::vector<int> res = twoSum(c.nums, c.target);
            std::sort(res.begin(), res.end());
            std::vector<int> exp = c.expected;
            std::sort(exp.begin(), exp.end());
            if (res == exp) {
                passed++;
            } else {
                std::cerr << "Test case " << i << " failed: Expected indices of elements adding to " 
                          << c.target << ", got mismatch." << std::endl;
            }
        } catch (const std::exception& e) {
            std::cerr << "Test case " << i << " errored: " << e.what() << std::endl;
        }
    }

    std::cout << "RESULT:" << passed << "/" << cases.size() << std::endl;
    return 0;
}

